prompt.output_schema:
{
  "photo_quality": "good | fair | poor, with a short reason",

  "site_type": {
    "value": "existing_road | kaccha_track | open_land | unclear",
    "confidence": "low | medium | high"
  },

  "recommended_mode": {
    "value": "repair | new_construction | unclear",
    "confidence": "low | medium | high",
    "reason": "short evidence-based reason"
  },

  "new_road_notes": {
    "terrain": "flat | sloping | uneven | not visible",
    "drainage_concerns": "short evidence-based statement",
    "obstacles": "trees, poles, structures, water body, none visible, or not visible",
    "cc_vs_bt_factors": "neutral factors only; never choose CC or BT"
  },

  "road_type": {
    "value": "earthen | moorum or gravel | WBM | bituminous (BT) | concrete (CC) | paver block | unclear",
    "confidence": "low | medium | high"
  },

  "surface_condition": "one or two short evidence-based sentences",

  "defects": [
    {
      "type": "pothole | alligator cracking | longitudinal crack | transverse crack | raveling | edge breaking | rutting | patching failure | waterlogging | missing or damaged drain | damaged kerb | faded marking | missing or damaged signboard | vegetation on shoulder | other",
      "severity": "minor | moderate | severe",
      "confidence": "low | medium | high",
      "note": "short evidence-based observation"
    }
  ],

  "suggested_works": [
    {
      "work": "short work name",
      "reason": "short evidence-based reason",
      "suggested_chapters": [
        "chapter names from allowed_ssr_chapters only"
      ],
      "search_keywords": [
        "keyword 1",
        "keyword 2"
      ],
      "confidence": "low | medium | high"
    }
  ],

  "suggested_parameters": [
    {
      "name": "parameter name",
      "why_needed": "short reason"
    }
  ],

  "limitations": "short explanation of what cannot be determined from the photograph"
}
